<script setup>
import { computed, ref } from 'vue'
import { dateTime, historyStatus, isHistoryActive, isHistoryDone } from './model.js'
import { href } from './navigation.js'
import { deliveryPage } from './useDelivery.js'
const props = defineProps({ items: Array, legacy: Array, loading: Boolean, error: String, hasMore: Boolean })
defineEmits(['retry', 'more'])
const query = ref(''), status = ref('all')
const filtered = computed(() => (props.items || []).filter(i => (!query.value || (i.title + i.run_id).toLowerCase().includes(query.value.trim().toLowerCase())) && (status.value === 'all' || (status.value === 'done' ? isHistoryDone(i) : isHistoryActive(i)))))
const older = computed(() => (props.legacy || []).filter(i => !query.value || i.title.toLowerCase().includes(query.value.trim().toLowerCase())))
</script>
<template><div class="page"><div class="section-heading"><h1>历史研究库</h1><span class="muted">研究报告与回测记录，可回看核对</span></div><div class="library-tools"><input v-model="query" type="search" aria-label="搜索历史研究" placeholder="搜索问题、标的或任务编号" /><select v-model="status" aria-label="研究状态"><option value="all">全部状态</option><option value="done">已成稿 / 检查完成</option><option value="active">执行中 / 成稿中</option></select><button class="btn" :disabled="loading" @click="$emit('retry')">刷新</button></div><p v-if="error" class="notice error-text" role="alert">{{ error }}</p><p v-if="loading && !items?.length" class="panel empty-state" role="status">正在读取历史记录…</p><div v-else-if="filtered.length" class="panel"><div v-for="item in filtered" :key="item.run_id" class="lib-row"><span class="tag tag-gold">{{ item.scenario === 'live' ? '实时研究' : item.scenario === 'backtest' ? '回测检查' : item.scenario === 'compare_live' || item.scenario === 'compare' ? '对比' : item.scenario === 'strategy' ? '策略回测' : '深研' }}</span><a class="lib-q" :href="href(deliveryPage(item), item.run_id)">{{ item.title }}</a><span v-if="item.report_version" class="num lib-subject">v{{ item.report_version }}</span><span v-else class="tag">{{ historyStatus(item) }}</span><time class="lib-date">{{ dateTime(item.created_at) }}</time></div></div><div v-else class="panel empty-state">{{ query || status !== 'all' ? '没有匹配的记录，尝试调整筛选条件。' : '还没有研究记录，去工作台运行第一个任务。' }} <a :href="href('workbench')">工作台</a></div><button v-if="hasMore" class="btn more-button" :disabled="loading" @click="$emit('more')">加载更多记录</button><section v-if="older.length && status === 'all'" class="workspace-section"><h2 class="section-title">既有调查档案 · 只读回看</h2><div class="panel"><div v-for="item in older" :key="item.investigation_id" class="lib-row"><span class="tag">归档</span><a class="lib-q" :href="href('legacy', item.investigation_id)">{{ item.title }}</a><time class="lib-date">{{ dateTime(item.created_at) }}</time></div></div></section></div></template>
